const raw = $json.content?.parts?.filter(p => !p.thought).map(p => p.text || '').join('') ?? $json.text ?? '';
const cleaned = raw.replace(/```json/gi,'').replace(/```/g,'').trim();
let data = null;
for (const c of (cleaned.match(/\{[\s\S]*\}/g) || []).reverse()) {
  try { const p = JSON.parse(c); if (p && typeof p.healthScore === 'number') { data = p; break; } } catch(e){}
}
const client = $('Validate Client').item.json;
if (!data) return { json: { ...client, parse_ok: false, error: 'AI output unparseable',
  healthScore: 50, riskLevel: 'at-risk', keyRiskFactors: ['unknown'], recommendedIntervention: 'Manual review needed', confidence: 0.5 } };
const confidence = typeof data.confidence === 'number' ? data.confidence : 0.7;
return { json: { ...client, ...data, confidence, parse_ok: true } };

